146	  /**
147	   * Generate a password variable for connection strings, supporting inline values,
148	   * environment variable lookups, and f-string formatting.
149	   * @param {string|undefined} password - Fallback password value.
150	   * @param {string} passwordPlaceholder - Environment variable name.
151	   * @param {boolean} inFString - If true, wrap for Python f-string.
152	   * @param {string} [variableName] - Variable name (default: "password").
153	   * @returns {string}
154	   *
155	   * @example
156	   * `printPassword("token123", "DATABRICKS_ACCESS_TOKEN", true, "access_token")`
157	   *
158	   * Returns:
159	   * ```python
160	   * _access_token = os.environ.get("DATABRICKS_ACCESS_TOKEN", "token123")
161	   * f"db://sample:{_access_token}@sample.com"
162	   * ```
163	   *
164	   * @example
165	   * `printPassword("token123", "DATABRICKS_ACCESS_TOKEN", false, "access_token")`
166	   *
167	   * Returns:
168	   * ```python
169	   * access_token = os.environ.get("DATABRICKS_ACCESS_TOKEN", "token123")
170	   * f"db://sample:access_token@sample.com"
171	   * ```
172	   */
173	  printPassword(
174	    password: string | undefined,
175	    passwordPlaceholder: string,
176	    inFString: boolean,
177	    variableName?: string,
178	  ): string {
179	    // Inline passwords should use printInFString, otherwise use print
180	    const printMethod = inFString
181	      ? this.printInFString.bind(this)
182	      : this.print.bind(this);
183	
184	    return isSecret(password)
185	      ? printMethod(variableName || "password", password)
186	      : printMethod(variableName || "password", passwordPlaceholder, password);
187	  }
